import {moleculeTasks,checkMolecule} from './covalent-builder.js?v=20261023-physicscomplete01';
import {renderDiagram,renderBond,enable3D} from './visual.js?v=20261023-physicscomplete01';
const $=s=>document.querySelector(s);
const text=(x,y,s,size=14,colour='#f8f6f2')=>`<text x="${x}" y="${y}" text-anchor="middle" fill="${colour}" font-size="${size}" font-family="sans-serif">${s}</text>`;
function moleculeSVG(t,b){
 const xy=t.atoms.length===2?[[130,135],[310,135]]:t.atoms.length===3?[[220,135],[110,135],[330,135]]:[[220,135],...[0,1,2,3].slice(0,t.atoms.length-1).map((_,i)=>{const a=-Math.PI/2+i*2*Math.PI/(t.atoms.length-1);return [220+110*Math.cos(a),135+90*Math.sin(a)];})];
 const mark=(x,y,cross)=>cross?`<path d="M${x-3} ${y-3}l6 6m-6 0l6 -6" stroke="#f0b4a6" stroke-width="2"/>`:`<circle cx="${x}" cy="${y}" r="3" fill="#d4dfe7"/>`;
 const sym=i=>i>0;
 let art=t.edges.map(([a,c],i)=>{const [x,y]=xy[a],[u,v]=xy[c],dx=u-x,dy=v-y,d=Math.hypot(dx,dy),px=-dy/d,py=dx/d;return Array.from({length:b.orders[i]},(_,k)=>{const offset=(k-(b.orders[i]-1)/2)*14,mx=(x+u)/2+px*offset,my=(y+v)/2+py*offset;return mark(mx-dx/d*5,my-dy/d*5,sym(a))+mark(mx+dx/d*5,my+dy/d*5,sym(c));}).join('');}).join('');
 art+=xy.map(([x,y],i)=>{let lone='';for(let j=0;j<b.lone[i];j++){const a=(j+.5)*2*Math.PI/Math.max(1,b.lone[i]),u=x+34*Math.cos(a),v=y+34*Math.sin(a);lone+=mark(u-4,v,sym(i))+mark(u+4,v,sym(i));}return `<circle cx="${x}" cy="${y}" r="22" fill="#182e44" stroke="#b7c8d6"/>${text(x,y+5,t.atoms[i],18)}${text(x,y+17,String(i+1),9)}${lone}`;}).join('');
 return `<svg class="lab-svg" viewBox="0 0 440 285" role="img" aria-label="Your outer-shell diagram for ${t.formula}; shared pairs ${b.orders.join(', ')}, lone pairs by atom ${b.lone.join(', ')}">${art}${text(220,280,'Dots / crosses track origins · flat layout, not molecular shape',10)}</svg>`;
}
export function mountCovalentWidget(lesson,p,root,{save,done,feedback}){
 const w=p.widget;const pass=s=>{p.widgetDone=true;save();done();feedback(s);};
 if(lesson.widget==='metallic-lab'){
 w.mode??='pure';w.slide??=0;w.passed??=[];w.task??=0;
 const tasks=[['What carries current through this solid metal?',['Delocalised electrons','Positive ions travelling down the wire'],0],['Why are differently sized atoms useful in an alloy?',['They remove every electron','They distort layers and hinder sliding'],1],['Why can a pure metal bend without simply falling apart?',['Layers can slide while metallic attraction persists','There are no forces holding its atoms together'],0]];
 const task=tasks[w.task];root.innerHTML=`<p>Compare a pure metal with an alloy. Slide the layer model, then explain each observation. This is a schematic, not a strength measurement.</p><label class="field-label" for="metalMode">Material</label><select id="metalMode" class="lab-select"><option value="pure">Pure metal</option><option value="alloy">Alloy · different atom sizes</option></select><label class="field-label" for="layerSlide">Attempt to slide layers</label><input id="layerSlide" type="range" min="0" max="100" value="${w.slide}"><div id="metalSummary" class="callout"></div><button id="metal3D" class="secondary">Explore metallic bonding in 3D</button><p><b>${w.task+1} / 3 · ${task[0]}</b></p><div class="choices">${task[1].map((s,i)=>`<button class="choice" data-metal-answer="${i}">${s}</button>`).join('')}</div><button class="secondary" id="nextMetalTask">Next explanation →</button><p>${w.passed.length} / 3 explanations correct</p>`;
 $('#metalMode').value=w.mode;
 const draw=()=>{let art='';for(let r=0;r<3;r++)for(let c=0;c<6;c++){const foreign=w.mode==='alloy'&&((r===1&&c===2)||(r===2&&c===4));const shift=r===1?w.slide*(w.mode==='alloy'?.12:.5):0;const x=65+c*57+shift,y=60+r*70+(w.mode==='alloy'&&r===1&&c===3?10:0);art+=`<circle cx="${x}" cy="${y}" r="${foreign?30:23}" fill="${foreign?'#ed8b78':'#b7c8d6'}"/>${text(x,y+5,'+',18,'#182e44')}`;}for(let i=0;i<14;i++){const x=48+(i*73)%350,y=32+(i*47)%210;art+=`<circle cx="${x}" cy="${y}" r="3" fill="#d4dfe7"/>`;}renderDiagram(w.mode==='alloy'?'Distorted layers':'Regular layers','Positive ions + delocalised electrons',`<svg class="lab-svg" viewBox="0 0 440 285" role="img" aria-label="${w.mode==='alloy'?'Different sizes distort the rows and obstruct sliding':'Regular rows of metal ions can slide'}">${art}${text(220,270,'Schematic slice · electrons are not to scale',11)}</svg>`,'MODEL · LAYER MOVEMENT IS SYMBOLIC');$('#metalSummary').textContent=w.mode==='alloy'?'Different sizes disturb regular layers. Sliding is hindered; metallic bonding remains.':'Regular layers can slide while attraction to delocalised electrons persists.';save();};
 $('#metalMode').onchange=e=>{w.mode=e.target.value;draw();};$('#layerSlide').oninput=e=>{w.slide=Number(e.target.value);draw();};$('#metal3D').onclick=()=>{enable3D();renderBond('metallic');};root.querySelectorAll('[data-metal-answer]').forEach(b=>b.onclick=()=>{if(Number(b.dataset.metalAnswer)===task[2]){if(!w.passed.includes(w.task))w.passed.push(w.task);save();feedback('Correct. '+task[1][task[2]]+'.');if(w.passed.length===3)pass('All three explanations correct: mobile electrons, persistent attraction and distorted layers.');}else feedback('Follow which particles can move and how the regular layers change. The positive ions do not flow through a solid wire.',true);});$('#nextMetalTask').onclick=()=>{w.task=(w.task+1)%3;save();mountCovalentWidget(lesson,p,root,{save,done,feedback});};draw();return;
 }
 const tasks=lesson.widget==='covalent-single'?moleculeTasks.slice(0,3):moleculeTasks.slice(3);
 w.task??=0;w.builds??={};w.passed??=[];const t=tasks[w.task%tasks.length];w.builds[t.id]??={orders:t.edges.map(()=>0),lone:t.atoms.map(()=>0)};const b=w.builds[t.id];
 root.innerHTML=`<p><b>Build ${t.formula} · molecule ${w.task%tasks.length+1} / ${tasks.length}</b></p><p>Choose the number of shared pairs for each connection, then the lone pairs on each numbered atom. A pair contains two electrons. Check your electron budget and outer shells.</p><div class="diagram-inputs">${t.edges.map(([a,c],i)=>`<label>Shared pairs: ${t.atoms[a]} ${a+1}–${t.atoms[c]} ${c+1}<input class="lab-input" type="number" min="0" max="3" id="pair${i}" value="${b.orders[i]}"></label>`).join('')}${t.atoms.map((a,i)=>`<label>Lone pairs: ${a} ${i+1}<input class="lab-input" type="number" min="0" max="4" id="lone${i}" value="${b.lone[i]}"></label>`).join('')}</div><button class="secondary" id="checkMolecule">Check my diagram</button><button class="secondary" id="nextMolecule">Next molecule →</button><p id="moleculeProgress">${w.passed.length} / ${tasks.length} diagrams correct</p><div class="callout">Outer-shell electrons only. Each connection uses one electron from each bonded atom per pair. The flat layout and symbols do not show shape, size or electron paths.</div>`;
 const draw=()=>{renderDiagram('Your electron-pair diagram',t.formula,moleculeSVG(t,b),'CONSTRUCTION · OUTER SHELLS ONLY');save();};
 const bind=(prefix,values)=>values.forEach((_,i)=>$('#'+prefix+i).oninput=e=>{values[i]=Math.max(0,Math.min(prefix==='pair'?3:4,Math.floor(Number(e.target.value)||0)));draw();});bind('pair',b.orders);bind('lone',b.lone);
 $('#checkMolecule').onclick=()=>{const result=checkMolecule(t,b.orders,b.lone);if(result.ok){if(!w.passed.includes(t.id))w.passed.push(t.id);save();$('#moleculeProgress').textContent=`${w.passed.length} / ${tasks.length} diagrams correct`;if(w.passed.length===tasks.length)pass('All diagrams built correctly. '+result.message);else feedback(result.message);}else feedback(result.message,true);};
 $('#nextMolecule').onclick=()=>{w.task=(w.task+1)%tasks.length;save();mountCovalentWidget(lesson,p,root,{save,done,feedback});};draw();
}
